// GetEndpoints retrieves a map of registered services that match the given filter.
// The filter parameter is used to filter the services based on certain criteria.
// It returns a map where the key is the full key and the value is the simply true.
// Existence of key means that the service is registered
// If an error occurs while retrieving the services, it returns an error.
func (a *AdapterV2) GetEndpoints(secondaryClient bool) (map[string]string, error) {
	start := time.Now()
	if a.Client == nil {
		return nil, errors.New("etcd client in nil")
	}

	services := struct {
		data map[string]string
	}{
		data: make(map[string]string),
	}

	clustername := utils.GetClusterName()
	if clustername == "" {
		metrics.EtcdFailure.WithLabelValues("getservices:GetClusterName", "").Inc()
		return nil, errors.New("CLUSTERNAME is not set")
	}

	client := a.Client
	if secondaryClient {
		log.Info().Msg("Fetching endpoints from secondary client")
		if a.SecondaryClient == nil {
			metrics.EtcdFailure.WithLabelValues("getservices:SecondaryClient", "").Inc()
			return nil, errors.New("Secondary etcd client in nil")
		}
		client = a.SecondaryClient
	}

	ctxWithTimeout, cancel := context.WithTimeout(a.ctx, 30*time.Second)
	defer cancel()
	res, err := client.KV.Get(ctxWithTimeout, EndpointPrefix+"/", clientv3.WithPrefix(), clientv3.WithLimit(0))
	if err != nil {
		metrics.EtcdFailure.WithLabelValues("getservices:Get", "").Inc()
		a.handleError(err)
		return nil, err
	}

	metrics.EtcdSuccess.WithLabelValues("getservices:Get", "").Inc()
	for _, kv := range res.Kvs {
		if validator.ValidateKeyPath(string(kv.Key)) {
			var endpoint servicev1.ServiceEndpoint
			err = endpoint.UnmarshalVT(kv.Value)
			if err != nil {
				metrics.EtcdFailure.WithLabelValues("getservices:UnmarshalVT", "").Inc()
				log.Error().Dict("custom_attributes", logger.Attrs().
					Str("status_code", string(logger.GALACTUS_ETCD_UNMARSHAL_FAILED)).
					Str("key", string(kv.Key)).
					Str("error", err.Error())).
					Msg(logger.Msg(logger.GALACTUS_ETCD_UNMARSHAL_FAILED))
				continue
			}
			isValid, err := validator.ValidateServiceEndpoint(&endpoint)
			if err != nil {
				metrics.EtcdFailure.WithLabelValues("getservices:ValidateServiceEndpoint", "").Inc()
				log.Error().Dict("custom_attributes", logger.Attrs().
					Str("status_code", string(logger.GALACTUS_ETCD_VALIDATION_FAILED)).
					Str("key", string(kv.Key)).
					Str("pod_ip", endpoint.Address.GetValue()).
					Str("error", err.Error())).
					Msg(logger.Msg(logger.GALACTUS_ETCD_VALIDATION_FAILED))
				continue
			}
			if !isValid {
				metrics.EtcdFailure.WithLabelValues("getservices:ValidateServiceEndpoint", "").Inc()
				log.Error().Dict("custom_attributes", logger.Attrs().
					Str("status_code", string(logger.GALACTUS_ETCD_VALIDATION_FAILED)).
					Str("key", string(kv.Key))).
					Msg(logger.Msg(logger.GALACTUS_ETCD_VALIDATION_FAILED))
				continue
			}

			// Validate the endpoint's clustername
			var cluster = ""
			var ok = false
			if cluster, ok = endpoint.Meta["cluster"]; !ok {
				continue
			}
			if cluster != clustername {
				continue
			}
			if kv.Lease > 0 {
				continue
			}
			services.data[string(kv.Key)] = endpoint.Version.GetValue()
		} else {
			metrics.EtcdFailure.WithLabelValues("getservices:ValidateKeyPath", "").Inc()
			continue
		}
	}

	log.Info().Msgf("GetEndpoints from Etcd took %s", time.Since(start))
	return services.data, nil
}

func (a *AdapterV2) getGrpcDialOptions() []grpc.DialOption {
	var opts []grpc.DialOption

	opts = append(opts, grpc.WithKeepaliveParams(keepalive.ClientParameters{
		Time:                utils.DefaultDiscoveryGrpcConnKeepaliveIntervalSeconds * time.Second,
		Timeout:             utils.DefaultDiscoveryGrpcConnKeepaliveTimeoutSeconds * time.Second,
		PermitWithoutStream: true,
	}))

	opts = append(opts, grpc.WithChainUnaryInterceptor(
		grpc_retry.UnaryClientInterceptor(
			grpc_retry.WithOnRetryCallback(func(ctx context.Context, attempt uint, err error) {
				log.Info().Msgf("unary call attempt=%d", attempt)
				if err != nil {
					metrics.EtcdFailure.WithLabelValues("getGrpcDialOptions:OnRetryCallback", "").Inc()
					log.Error().Dict("custom_attributes", logger.Attrs().
						Str("status_code", string(logger.GALACTUS_ETCD_UNARY_CALL_FAILED)).
						Uint("attempt", attempt).
						Str("error", err.Error())).
						Msg(logger.Msg(logger.GALACTUS_ETCD_UNARY_CALL_FAILED))
				}
			}),
			grpc_retry.WithPerRetryTimeout(utils.DefaultDiscoveryGrpcApiTimeoutMilliseconds*time.Millisecond),
			grpc_retry.WithCodes(utils.DefaultDiscoveryGrpcRetriableStatusCodes...),
			grpc_retry.WithMax(utils.DefaultDiscoveryGrpcApiRetries),
			grpc_retry.WithBackoff(grpc_retry.BackoffExponentialWithJitter(utils.DefaultDiscoveryGrpcApiExponentialBackoffDurationMilliseconds*time.Millisecond, utils.DefaultDiscoveryGrpcApiExponentialBackoffJitter))),
		grpc_timeout.UnaryClientInterceptor(utils.DefaultDiscoveryGrpcApiTimeoutMilliseconds*time.Millisecond),
		grpc_prometheus.UnaryClientInterceptor,
	))

	opts = append(opts, grpc.WithChainStreamInterceptor(
		grpc_prometheus.StreamClientInterceptor,
	))

	return opts
}

func (a *AdapterV2) New(zonalHosts []string, allHosts []string, secondaryHosts []string, dialTimeoutMs int, multiEnityEnabled bool, quit chan bool) (*AdapterV2, error) {
	if len(zonalHosts) == 0 || len(allHosts) == 0 || (multiEnityEnabled && len(secondaryHosts) == 0) || len(zonalHosts) > len(allHosts) {
		return nil, fmt.Errorf("invalid etcd configuration: zonal=%d all=%d secondary=%d multiEntity=%v", len(zonalHosts), len(allHosts), len(secondaryHosts), multiEnityEnabled)
	}
	a.MultiEntityEnabled = &atomic.Bool{}
	a.MultiEntityEnabled.Store(multiEnityEnabled)
	a.MultiEntityServices = &sync.Map{}
	a.zonalHosts = zonalHosts
	a.allHosts = allHosts
	a.secondaryHosts = secondaryHosts
	etcdConfig := clientv3.Config{
		Endpoints:   zonalHosts,
		DialOptions: a.getGrpcDialOptions(),
		DialTimeout: time.Duration(dialTimeoutMs) * time.Millisecond,
	}
	etcdClient, err := clientv3.New(etcdConfig)
	if err != nil {
		return nil, fmt.Errorf("failed to connect to primary etcd: %w", err)
	}

	log.Info().Msgf("Discovery endpoint: %s, state: %s", etcdClient.ActiveConnection().Target(), etcdClient.ActiveConnection().GetState().String())
	connectCtx, connectCancel := context.WithTimeout(context.Background(), time.Duration(dialTimeoutMs)*time.Millisecond)
	defer connectCancel()
	if !etcdClient.ActiveConnection().WaitForStateChange(connectCtx, etcdClient.ActiveConnection().GetState()) {
		etcdClient.Close()
		return nil, fmt.Errorf("primary etcd connection timed out after %dms: endpoint=%s state=%s", dialTimeoutMs, etcdClient.ActiveConnection().Target(), etcdClient.ActiveConnection().GetState().String())
	}
	log.Info().Msgf("Discovery endpoint: %s, state: %s", etcdClient.ActiveConnection().Target(), etcdClient.ActiveConnection().GetState().String())
	log.Info().Msg("connection to etcd in progress...")
	a.Client = etcdClient

	if multiEnityEnabled && len(secondaryHosts) > 0 {
		log.Info().Msgf("Multi-entity enabled, connecting to secondary etcd cluster: %s", strings.Join(secondaryHosts, ","))
		etcdConfig := clientv3.Config{
			Endpoints:   secondaryHosts,
			DialOptions: a.getGrpcDialOptions(),
			DialTimeout: time.Duration(dialTimeoutMs) * time.Millisecond,
		}
		secondaryEtcdClient, err := clientv3.New(etcdConfig)
		if err != nil {
			return nil, fmt.Errorf("failed to connect to secondary etcd: %w", err)
		}
		log.Info().Msgf("Discovery endpoint: %s, state: %s", secondaryEtcdClient.ActiveConnection().Target(), secondaryEtcdClient.ActiveConnection().GetState().String())
		secondaryConnectCtx, secondaryConnectCancel := context.WithTimeout(context.Background(), time.Duration(dialTimeoutMs)*time.Millisecond)
		defer secondaryConnectCancel()
		if !secondaryEtcdClient.ActiveConnection().WaitForStateChange(secondaryConnectCtx, secondaryEtcdClient.ActiveConnection().GetState()) {
			secondaryEtcdClient.Close()
			return nil, fmt.Errorf("secondary etcd connection timed out after %dms: endpoint=%s state=%s", dialTimeoutMs, secondaryEtcdClient.ActiveConnection().Target(), secondaryEtcdClient.ActiveConnection().GetState().String())
		}
		log.Info().Msgf("Discovery endpoint: %s, state: %s", secondaryEtcdClient.ActiveConnection().Target(), secondaryEtcdClient.ActiveConnection().GetState().String())
		a.SecondaryClient = secondaryEtcdClient
	}

	// Create parent context cancelled when quit channel closes.
	// All operation contexts derive from this, enabling coordinated cancellation on shutdown.
	ctx, cancel := context.WithCancel(context.Background())
	a.ctx = ctx
	go func() {
		<-quit
		time.Sleep(30 * time.Second)
		cancel()
	}()

	go func() {
		ticker := time.NewTicker(utils.DiscoveryStatusCheckIntervalSeconds * time.Second)
		for {
			select {
			case <-quit:
				ticker.Stop()
				return
			case <-ticker.C:
				state := a.Client.ActiveConnection().GetState().String()
				endpoint := a.Client.ActiveConnection().Target()
				EtcdConnectionState.Store(state)

				log.Info().Msgf("Etcd status: %s, endpoint: %s", state, endpoint)

				if PrimaryEtcdClientReady.Load() {
					log.Info().Msgf("Primary etcd client is ready, switching endpoints to %s",
						strings.Join(a.zonalHosts, ","),
					)
					a.Client.SetEndpoints(a.zonalHosts...)
					DiscoveryInNotReadyStateCount.Store(0)
					PrimaryEtcdClientReady.Store(false)
					IsDiscoveryReady.Store(true)
					continue
				}

				if state == "READY" {
					IsDiscoveryReady.Store(true)
					metrics.RecordDiscoveryServerConnectionReady(endpoint)
					DiscoveryInNotReadyStateCount.Store(0)
					continue
				}

				// Not ready case
				DiscoveryInNotReadyStateCount.Add(1)
				metrics.RecordDiscoveryServerConnectionNotReady(endpoint)

				if DiscoveryInNotReadyStateCount.Load() > 3 {
					if strings.Join(a.Client.Endpoints(), ",") != strings.Join(a.allHosts, ",") {
						log.Warn().Msgf("Etcd not ready for %d seconds, switching to endpoints: %s",
							DiscoveryInNotReadyStateCount.Load()*utils.DiscoveryStatusCheckIntervalSeconds,
							strings.Join(a.allHosts, ","),
						)
						a.checkPrimaryEtcdConnection(quit)
						a.Client.SetEndpoints(a.allHosts...)
					}
					DiscoveryInNotReadyStateCount.Store(0)
					IsDiscoveryReady.Store(false)
				}
			}

		}
	}()

	return a, nil
}

